import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { API_URL, testConnection } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [originalImage, setOriginalImage] = useState(null);
  const [processedImage, setProcessedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [accuracy, setAccuracy] = useState(null);
  const [serverConnected, setServerConnected] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    const checkConnection = async () => {
      const result = await testConnection();
      setServerConnected(result.success);
      if (!result.success) {
        setError(result.error);
      }
    };
    checkConnection();
  }, []);

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setOriginalImage(event.target.result);
        setProcessedImage(null);
        setAccuracy(null);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setOriginalImage(event.target.result);
        setProcessedImage(null);
        setAccuracy(null);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.currentTarget.classList.add('dragover');
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.currentTarget.classList.remove('dragover');
  };

  const processImage = async () => {
    if (!originalImage) {
      setError('Please select an image first');
      return;
    }

    setLoading(true);
    setError(null);
    setAccuracy(null);

    try {
      const response = await fetch(originalImage);
      const blob = await response.blob();

      const fileInput = fileInputRef.current;
      const originalFile = fileInput?.files?.[0];
      const filename = originalFile?.name || 'image.jpg';

      const formData = new FormData();
      formData.append('image', blob, filename);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const result = await axios.post(`${API_URL}/process-image`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      if (result.data.success) {
        setProcessedImage(`data:image/png;base64,${result.data.processed_image}`);
        setAccuracy(result.data.accuracy);
      } else {
        setError(result.data.error || 'Failed to process image');
      }
    } catch (err) {
      console.error('Image processing error:', err);
      const errorMessage = err.response?.data?.error || 
                           err.message || 
                           'Error processing image. Please check if the backend server is running.';
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="component-container">
      <h2>Image Processor</h2>

      <div
        className="upload-area"
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => fileInputRef.current?.click()}
      >
        <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileSelect} />
        <p>Click or drag and drop an image here</p>
        <p style={{ fontSize: '14px', color: '#666', marginTop: '10px' }}>
          Supported formats: JPG, PNG, GIF
        </p>
      </div>

      {error && <div className="error">{error}</div>}

      {(originalImage || processedImage) && (
        <div className="image-preview" style={{ display: 'flex', gap: '20px', justifyContent: 'center', flexWrap: 'wrap', marginTop: '20px' }}>
          {originalImage && (
            <div style={{ textAlign: 'center', flex: '1', minWidth: '300px' }}>
              <h3>Original</h3>
              <img src={originalImage} alt="Original" style={{ maxWidth: '100%', maxHeight: '400px', borderRadius: '8px' }} />
            </div>
          )}
          {processedImage && (
            <div style={{ textAlign: 'center', flex: '1', minWidth: '300px' }}>
              <h3>Processed</h3>
              <img src={processedImage} alt="Processed" style={{ maxWidth: '100%', maxHeight: '400px', borderRadius: '8px' }} />
              {accuracy !== null && (
                <p style={{ marginTop: '5px', fontSize: '14px', color: '#333' }}>
                  Filter Accuracy: <strong>{accuracy}%</strong>
                </p>
              )}
            </div>
          )}
        </div>
      )}

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button className="button" onClick={processImage} disabled={!originalImage || loading}>
          {loading ? 'Processing...' : 'Process Image'}
        </button>
      </div>
    </div>
  );
};

export default ImageProcessor;
